const { addPageBadge, addTitle, addTopRule, addBulletList, addSource } = require("./helpers");

const slideConfig = {
  type: "content",
  index: 3,
  title: "Global Fossil Fuel CO₂ Emissions Grew Six-Fold: 6 Billion to 35+ Billion Tonnes"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addTopRule(slide, theme);
  addTitle(slide, theme, slideConfig.title);

  // Left: key inflection points
  slide.addShape(slide.ShapeType.roundRect, {
    x: 0.7,
    y: 1.25,
    w: 3.7,
    h: 3.9,
    fill: { color: "ffffff" },
    line: { color: theme.secondary, transparency: 40 }
  });
  slide.addText("Inflection points", {
    x: 0.95,
    y: 1.4,
    w: 3.2,
    h: 0.35,
    fontFace: theme.fonts.header,
    fontSize: 16,
    bold: true,
    color: theme.primary
  });
  addBulletList(
    slide,
    theme,
    [
      "1950: ~6 billion tonnes (Bt)",
      "1990: >20 Bt", 
      "Today (2024): >35 Bt",
      "Growth slowed recently, but has not yet peaked"
    ],
    { x: 0.95, y: 1.85, w: 3.2, h: 3.1, fontSize: 14 }
  );

  // Right: stylized line chart (no fabricated intermediate values)
  slide.addShape(slide.ShapeType.roundRect, {
    x: 4.65,
    y: 1.25,
    w: 4.75,
    h: 3.9,
    fill: { color: "ffffff" },
    line: { color: theme.secondary, transparency: 40 }
  });
  slide.addText("Trajectory (illustrative)", {
    x: 4.9,
    y: 1.4,
    w: 4.25,
    h: 0.35,
    fontFace: theme.fonts.header,
    fontSize: 16,
    bold: true,
    color: theme.primary
  });

  // Axes
  slide.addShape(slide.ShapeType.line, {
    x: 5.05,
    y: 4.85,
    w: 3.95,
    h: 0,
    line: { color: theme.secondary, width: 2 }
  });
  slide.addShape(slide.ShapeType.line, {
    x: 5.05,
    y: 4.85,
    w: 0,
    h: -2.7,
    line: { color: theme.secondary, width: 2 }
  });

  // Line with three anchored points (1950, 1990, 2024)
  const pts = [
    { x: 5.25, y: 4.35, label: "1950\n~6 Bt" },
    { x: 6.85, y: 3.35, label: "1990\n>20 Bt" },
    { x: 8.85, y: 2.35, label: "2024\n>35 Bt" }
  ];
  // segments
  slide.addShape(slide.ShapeType.line, {
    x: pts[0].x,
    y: pts[0].y,
    w: pts[1].x - pts[0].x,
    h: pts[1].y - pts[0].y,
    line: { color: theme.accent, width: 4 }
  });
  slide.addShape(slide.ShapeType.line, {
    x: pts[1].x,
    y: pts[1].y,
    w: pts[2].x - pts[1].x,
    h: pts[2].y - pts[1].y,
    line: { color: theme.accent, width: 4 }
  });

  pts.forEach((p) => {
    slide.addShape(slide.ShapeType.oval, {
      x: p.x - 0.08,
      y: p.y - 0.08,
      w: 0.16,
      h: 0.16,
      fill: { color: theme.accent },
      line: { color: theme.accent }
    });
    slide.addText(p.label, {
      x: p.x - 0.45,
      y: p.y + 0.12,
      w: 0.9,
      h: 0.5,
      fontFace: theme.fonts.body,
      fontSize: 10,
      color: theme.primary,
      align: "center"
    });
  });

  slide.addText("(Reference visual: figure_2.jpg)", {
    x: 4.9,
    y: 5.05,
    w: 4.4,
    h: 0.25,
    fontFace: theme.fonts.body,
    fontSize: 10,
    color: theme.secondary
  });

  addSource(slide, theme, "Source: Our World in Data — CO₂ and Greenhouse Gas Emissions (Global Carbon Budget 2025)." );
  addPageBadge(slide, theme, 3, 9);
  return slide;
}

module.exports = { createSlide, slideConfig };

