const path = require("path");
const { addPageBadge, addTitle, addTopRule, addSource } = require("./helpers");

const slideConfig = {
  type: "content",
  index: 4,
  title: "China Now Emits Over 12 Billion Tonnes — More Than Double the United States"
};

function addBarRow(slide, theme, { y, label, valueText, shareText, wMax, wVal, color }) {
  slide.addText(label, {
    x: 0.75,
    y,
    w: 2.1,
    h: 0.28,
    fontFace: theme.fonts.body,
    fontSize: 12,
    color: theme.primary
  });
  // Track
  slide.addShape(slide.ShapeType.roundRect, {
    x: 2.85,
    y: y + 0.06,
    w: wMax,
    h: 0.18,
    fill: { color: theme.light },
    line: { color: theme.light }
  });
  // Value bar
  slide.addShape(slide.ShapeType.roundRect, {
    x: 2.85,
    y: y + 0.06,
    w: wVal,
    h: 0.18,
    fill: { color },
    line: { color }
  });
  slide.addText(`${valueText}  •  ${shareText}`, {
    x: 2.85 + wMax + 0.15,
    y: y - 0.01,
    w: 3.0,
    h: 0.3,
    fontFace: theme.fonts.body,
    fontSize: 12,
    color: theme.secondary
  });
}

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addTopRule(slide, theme);
  addTitle(slide, theme, slideConfig.title);

  // Left: data-driven bar comparison from provided table
  slide.addShape(slide.ShapeType.roundRect, {
    x: 0.65,
    y: 1.15,
    w: 8.75,
    h: 2.55,
    fill: { color: "ffffff" },
    line: { color: theme.secondary, transparency: 40 }
  });
  slide.addText("Annual CO₂ emissions (fossil fuels + industry)", {
    x: 0.85,
    y: 1.3,
    w: 8.3,
    h: 0.35,
    fontFace: theme.fonts.header,
    fontSize: 16,
    bold: true,
    color: theme.primary
  });

  const maxBt = 12.5;
  const wMax = 4.4;
  const rows = [
    { label: "China", bt: 12.5, valueText: "~12.5 Bt", shareText: "~27%", color: theme.accent },
    { label: "United States", bt: 5.0, valueText: "~5.0 Bt", shareText: "~14%", color: theme.primary },
    { label: "India", bt: 3.0, valueText: "~3.0 Bt", shareText: "~8%", color: theme.secondary },
    { label: "EU-27", bt: 2.7, valueText: "~2.7 Bt", shareText: "~7%", color: theme.secondary }
  ];
  rows.forEach((r, i) => {
    addBarRow(slide, theme, {
      y: 1.75 + i * 0.48,
      label: r.label,
      valueText: r.valueText,
      shareText: r.shareText,
      wMax,
      wVal: (r.bt / maxBt) * wMax,
      color: r.color
    });
  });

  // Right: reference figure (provided)
  const imgPath = path.join(__dirname, "imgs", "figure_3.jpg");
  slide.addImage({ path: imgPath, x: 0.65, y: 3.9, w: 8.75, h: 1.45 });
  slide.addText("Reference visual: figure_3.jpg (Annual CO₂ emissions by country)", {
    x: 0.7,
    y: 5.35,
    w: 8.7,
    h: 0.25,
    fontFace: theme.fonts.body,
    fontSize: 10,
    color: theme.secondary
  });

  // Key narrative callouts (from brief)
  slide.addShape(slide.ShapeType.roundRect, {
    x: 9.5,
    y: 1.15,
    w: 0.45,
    h: 4.2,
    fill: { color: theme.accent },
    line: { color: theme.accent }
  });
  slide.addText("US peaked near ~6 Bt around 2005; now ~5 Bt (declining)", {
    x: 0.85,
    y: 3.65,
    w: 8.3,
    h: 0.25,
    fontFace: theme.fonts.body,
    fontSize: 12,
    color: theme.primary
  });

  addSource(slide, theme, "Source: Our World in Data — CO₂ and Greenhouse Gas Emissions (Global Carbon Budget 2025); see figure_3.jpg." );
  addPageBadge(slide, theme, 4, 9);
  return slide;
}

module.exports = { createSlide, slideConfig };

