const { addPageBadge, addTitle, addTopRule, addBulletList, addSource } = require("./helpers");

const slideConfig = {
  type: "content",
  index: 8,
  title: "Energy Mix Explains Why France Emits Far Less Per Capita Than Germany"
};

function addTable(slide, theme) {
  const x = 0.75;
  const y = 1.4;
  const w = 8.9;
  const rowH = 0.48;
  const colWs = [2.6, 3.0, 3.3];

  // Header background
  slide.addShape(slide.ShapeType.roundRect, {
    x,
    y,
    w,
    h: rowH,
    fill: { color: theme.primary },
    line: { color: theme.primary }
  });
}

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };
  addTopRule(slide, theme);
  addTitle(slide, theme, slideConfig.title);

  // Intro bullets (from brief only)
  addBulletList(
    slide,
    theme,
    [
      "Similar living standards can yield very different per-capita CO₂ depending on energy sources.",
      "France and the UK: higher nuclear and renewable shares → lower per-capita emissions.",
      "Germany and the Netherlands: higher fossil fuel share → higher per-capita emissions."
    ],
    { x: 0.75, y: 1.15, w: 8.9, h: 0.95, fontSize: 13 }
  );

  // Comparison table (qualitative, no fabricated numbers)
  const tableX = 0.75;
  const tableY = 2.35;
  const tableW = 8.9;
  const rowH = 0.55;
  const colWs = [2.4, 3.2, 3.3];

  // Header
  slide.addShape(slide.ShapeType.roundRect, {
    x: tableX,
    y: tableY,
    w: tableW,
    h: rowH,
    fill: { color: theme.primary },
    line: { color: theme.primary }
  });
  const headers = ["Comparison", "Energy mix (high level)", "Per-capita CO₂ (direction)" ];
  let cx = tableX;
  headers.forEach((h, i) => {
    slide.addText(h, {
      x: cx + 0.15,
      y: tableY + 0.15,
      w: colWs[i] - 0.3,
      h: rowH - 0.1,
      fontFace: theme.fonts.body,
      fontSize: 12,
      color: theme.light,
      bold: false
    });
    cx += colWs[i];
  });

  const rows = [
    ["France / UK", "Higher nuclear + renewables", "Lower"],
    ["Germany / Netherlands", "Higher fossil fuel share", "Higher"]
  ];

  rows.forEach((r, idx) => {
    const y = tableY + rowH * (idx + 1);
    slide.addShape(slide.ShapeType.rect, {
      x: tableX,
      y,
      w: tableW,
      h: rowH,
      fill: { color: idx % 2 === 0 ? "ffffff" : theme.light },
      line: { color: theme.secondary, transparency: 60 }
    });

    let x = tableX;
    r.forEach((cell, i) => {
      slide.addText(cell, {
        x: x + 0.15,
        y: y + 0.16,
        w: colWs[i] - 0.3,
        h: rowH - 0.1,
        fontFace: theme.fonts.body,
        fontSize: 12,
        color: theme.primary,
        bold: false
      });
      x += colWs[i];
    });
  });

  // Emissions context note (from brief)
  slide.addShape(slide.ShapeType.roundRect, {
    x: 0.75,
    y: 3.65,
    w: 8.9,
    h: 1.0,
    fill: { color: theme.accent },
    line: { color: theme.accent }
  });
  slide.addText(
    "Policy implication: decarbonizing electricity supply can reduce per-capita CO₂ without changing prosperity.",
    {
      x: 0.95,
      y: 3.85,
      w: 8.5,
      h: 0.6,
      fontFace: theme.fonts.body,
      fontSize: 13,
      color: theme.light
    }
  );

  addSource(slide, theme, "Source: Our World in Data — CO₂ and Greenhouse Gas Emissions (Global Carbon Budget 2025)." );
  addPageBadge(slide, theme, 8, 9);
  return slide;
}

module.exports = { createSlide, slideConfig };

